"""The script_annotations_util module contains functionality for the script annotations feature when used with the runner."""

import json
import os
import re
import sys
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Tuple, Type, TypeVar, Union, cast

if sys.version_info >= (3, 10):
    from types import NoneType
else:
    NoneType = type(None)

from hera.shared._pydantic import BaseModel, get_field_annotations, get_fields
from hera.shared._type_util import (
    get_unsubscripted_type,
    get_workflow_annotation,
    origin_type_issubtype,
    unwrap_annotation,
)
from hera.shared.serialization import serialize
from hera.workflows import Artifact, Parameter
from hera.workflows.artifact import ArtifactLoader
from hera.workflows.io.v1 import Output as OutputV1

try:
    from hera.workflows.io.v2 import Output as OutputV2
except ImportError:
    from hera.workflows.io.v1 import Output as OutputV2  # type: ignore


def _get_outputs_path(destination: Union[Parameter, Artifact]) -> Path:
    """Get the path from the destination annotation using the defined outputs directory."""
    path = Path(os.environ.get("hera__outputs_directory", "/tmp/hera-outputs"))
    if isinstance(destination, Parameter) and destination.name:
        path = path / f"parameters/{destination.name}"
    elif isinstance(destination, Artifact):
        if destination.path:
            path = Path(destination.path)
        elif destination.name:
            path = path / f"artifacts/{destination.name}"
    return path


def _get_artifact_path(artifact_annotation: Artifact) -> Path:
    """Get the path for an artifact, handling path resolution properly."""
    if artifact_annotation.path:
        return Path(artifact_annotation.path)

    # For input artifacts, determine the default path
    if not artifact_annotation.output:
        # This is an input artifact, use the default input path
        from hera.workflows.artifact import _DEFAULT_ARTIFACT_INPUT_DIRECTORY
        if _DEFAULT_ARTIFACT_INPUT_DIRECTORY:
            path = Path(_DEFAULT_ARTIFACT_INPUT_DIRECTORY) / artifact_annotation.name
            return path
        # Fallback to default behavior
        return Path(f"/tmp/hera-outputs/artifacts/{artifact_annotation.name}")

    # For output artifacts, use the default outputs path
    return Path(os.environ.get("hera__outputs_directory", "/tmp/hera-outputs")) / f"artifacts/{artifact_annotation.name}"


def _get_dumper_function(destination: Union[Parameter, Artifact]) -> Callable:
    if isinstance(destination, Parameter) and destination.dumps is not None:
        return destination.dumps

    # Special handling for non-base Pydantic models
    if isinstance(destination, Parameter) and hasattr(destination, 'dumps') and destination.dumps is None:
        # If it's a parameter with dumps=None, we should use our enhanced serialize function
        # that handles Pydantic models properly
        return serialize

    # Special handling for Artifact outputs - if they have a dumps function, use it
    if isinstance(destination, Artifact) and destination.dumps is not None:
        return destination.dumps

    return serialize


def get_annotated_input_param(
    func_param_name: str,
    param_annotation: Parameter,
    kwargs: Dict[str, str],
) -> str:
    """Get the value from a given function param and its annotation.

    Return the string value from the kwargs dict,
    which could be from the param_annotation.name if given, or func_param_name.
    """
    # Try multiple approaches for parameter lookup in order of preference:
    # 1. Exact match with annotation name
    # 2. Exact match with function parameter name  
    # 3. Kebab-case to snake_case conversion of annotation name
    # 4. Kebab-case to snake_case conversion of function parameter name

    # Check for exact match with annotation name
    if param_annotation.name and param_annotation.name in kwargs:
        return kwargs[param_annotation.name]

    # Check for exact match with function parameter name
    if func_param_name in kwargs:
        return kwargs[func_param_name]

    # Check for kebab-case to snake_case conversion of annotation name
    if param_annotation.name:
        snake_case_name = re.sub(r'-([a-z])', lambda m: '_' + m.group(1), param_annotation.name)
        if snake_case_name in kwargs:
            return kwargs[snake_case_name]

    # Check for kebab-case to snake_case conversion of function parameter name
    snake_case_func_param_name = re.sub(r'-([a-z])', lambda m: '_' + m.group(1), func_param_name)
    if snake_case_func_param_name in kwargs:
        return kwargs[snake_case_func_param_name]

    raise RuntimeError(
        f"Parameter {param_annotation.name if param_annotation.name else func_param_name} was not given a value"
    )


def load_param_input(
    param_value: str,
    loader: Optional[Callable[[str], Any]],
) -> Any:
    """Load parameter input with proper error handling."""
    try:
        return param_value if loader is None else loader(param_value)
    except Exception as e:
        raise RuntimeError(f"Failed to load parameter value '{param_value}' with loader: {str(e)}")


def get_annotated_output_param(param_annotation: Parameter) -> Path:
    if param_annotation.value_from and param_annotation.value_from.path:
        path = Path(param_annotation.value_from.path)
    else:
        path = _get_outputs_path(param_annotation)
    # Automatically create the parent directory (if required)
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def get_annotated_artifact_value(param_name: str, artifact_annotation: Artifact) -> Union[Path, Any]:
    """Get the value of the given Artifact annotation.

    If the artifact is an output, return the path it will write to.
    If the artifact is an input, and it has an ArtifactLoader enum as its loader, return the
    loaded value according to the predefined behaviour (json obj, path or string), otherwise,
    if the loader is a Callable, it is used directly to load the value.

    As Artifacts are always Annotated in function parameters, we don't need to consider
    the `kwargs` or the function parameter name.
    """
    if artifact_annotation.output:
        if artifact_annotation.path:
            path = Path(artifact_annotation.path)
        else:
            path = _get_outputs_path(artifact_annotation)
        # Automatically create the parent directory (if required)
        path.parent.mkdir(parents=True, exist_ok=True)
        return path

    # For input artifacts, construct the path properly
    if not artifact_annotation.path:
        # This is an input artifact without explicit path - use the default input path resolution
        from hera.workflows.artifact import _DEFAULT_ARTIFACT_INPUT_DIRECTORY
        if _DEFAULT_ARTIFACT_INPUT_DIRECTORY:
            path = Path(_DEFAULT_ARTIFACT_INPUT_DIRECTORY) / artifact_annotation.name
            artifact_annotation.path = str(path)
        else:
            # Fallback to default behavior
            path = Path(f"/tmp/hera-outputs/artifacts/{artifact_annotation.name}")
            artifact_annotation.path = str(path)

    # Handle custom loaders for non-base model classes
    if artifact_annotation.loads is not None:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            with path.open() as f:
                return artifact_annotation.loads(f.read())
        except Exception as e:
            # If there's an error reading or loading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to load artifact from {path}: {str(e)}")

    if artifact_annotation.loader == ArtifactLoader.json.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            with path.open() as f:
                return json.load(f)
        except Exception as e:
            # If there's an error reading or loading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to load JSON artifact from {path}: {str(e)}")

    if artifact_annotation.loader == ArtifactLoader.file.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            return path.read_text()
        except Exception as e:
            # If there's an error reading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to read artifact file {path}: {str(e)}")

    if artifact_annotation.loader is None:
        # For artifacts with no specific loader, return the path directly
        return artifact_annotation.path
    elif artifact_annotation.loadb is not None:
        # Handle bytes loading using loadb method
        path = Path(artifact_annotation.path)
        if not path.exists():
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            return artifact_annotation.loadb(path.read_bytes())
        except Exception as e:
            raise RuntimeError(f"Failed to load bytes artifact from {path}: {str(e)}")
    else:
        raise RuntimeError(f"Artifact {artifact_annotation.name} was not given a value")


T = TypeVar("T", bound=Type[BaseModel])


def map_runner_input(
    runner_input_class: T,
    kwargs: Dict[str, str],
) -> T:
    """Map argo input kwargs to the fields of the given Input, return an instance of the class.

    If the field is annotated, we look for the kwarg with the name from the annotation (Parameter or Artifact).
    Otherwise, we look for the kwarg with the name of the field.
    """
    input_model_obj = {}

    def load_parameter_value(
        value: str,
        value_type: type,
        loader: Optional[Callable[[str], Any]] = None,
    ) -> Any:
        if origin_type_issubtype(value_type, (str, NoneType)):
            return value

        if loader is not None:
            return load_param_input(value, loader)

        try:
            return json.loads(value)
        except json.JSONDecodeError:
            # If JSON parsing fails, return the raw value
            return value

    runner_input_annotations = get_field_annotations(runner_input_class)

    def map_field(
        field: str,
        kwargs: Dict[str, str],
    ) -> Any:
        annotation = runner_input_annotations.get(field)
        assert annotation is not None, "Input fields must be type-annotated"  # Note: not necessarily with `Annotated`
        ann_type = unwrap_annotation(annotation)

        if param_or_artifact := get_workflow_annotation(annotation):
            if isinstance(param_or_artifact, Parameter):
                assert not param_or_artifact.output
                return load_parameter_value(
                    get_annotated_input_param(field, param_or_artifact, kwargs),
                    ann_type,
                    param_or_artifact.loads,
                )
            else:
                return get_annotated_artifact_value(field, param_or_artifact)
        else:
            return load_parameter_value(kwargs[field], ann_type)

    for field in get_fields(runner_input_class):
        input_model_obj[field] = map_field(field, kwargs)

    return cast(T, runner_input_class.parse_obj(input_model_obj))


def _save_annotated_return_outputs(
    function_outputs: Union[Tuple[Any], Any],
    output_annotations: List[Union[Tuple[type, Union[Parameter, Artifact]], Union[Type[OutputV1], Type[OutputV2]]]],
) -> Optional[Union[OutputV1, OutputV2]]:
    """Save the outputs of the function to the specified output destinations.

    The output values are matched with the output annotations and saved using the schema:
    <parent_directory>/artifacts/<name>
    <parent_directory>/parameters/<name>
    If the artifact path or parameter value_from.path is specified, that is used instead.
    <parent_directory> can be provided by the user or is set to /tmp/hera-outputs by default
    """
    if not isinstance(function_outputs, tuple):
        function_outputs = [function_outputs]
    if len(function_outputs) != len(output_annotations):
        raise ValueError("The number of outputs does not match the annotation")

    if os.environ.get("hera__script_pydantic_io", None) is not None:
        return_obj = None

    for output_value, dest in zip(function_outputs, output_annotations):
        if isinstance(output_value, (OutputV1, OutputV2)):
            if os.environ.get("hera__script_pydantic_io", None) is None:
                raise ValueError("hera__script_pydantic_io environment variable is not set")

            return_obj = output_value

            for field, value in output_value.dict().items():
                if field in {"exit_code", "result"}:
                    continue

                matching_output = output_value._get_output(field)
                path = _get_outputs_path(matching_output)
                _write_to_path(path, value, _get_dumper_function(matching_output))
        else:
            assert isinstance(dest, tuple)

            # Extract the actual type from the annotation for comparison
            annotated_type = dest[0]

            # Handle both regular types and Annotated types for proper type checking
            from typing import get_origin, get_args
            actual_type = annotated_type

            # If it's an Annotated type, extract the underlying type
            if hasattr(actual_type, '__metadata__') or (hasattr(actual_type, '__args__') and len(get_args(actual_type)) > 0):
                try:
                    # Try to get the underlying type from Annotated wrapper
                    args = get_args(actual_type)
                    if args:
                        actual_type = args[0]
                except Exception:
                    pass

            # Get the actual type for comparison
            from hera.shared._type_util import get_unsubscripted_type
            actual_type = get_unsubscripted_type(actual_type)

            # Special handling for generic types like typing.Dict[str, str] and typing.List[str]
            # Check if we're dealing with generic types that should match their underlying types
            if hasattr(actual_type, '__origin__'):
                # For generic types like Dict, List, etc., check if the output_value is the corresponding concrete type
                origin = get_origin(actual_type)
                if origin is dict:
                    # For Dict, check if output_value is a dict
                    if not isinstance(output_value, dict):
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )
                elif origin is list:
                    # For List, check if output_value is a list
                    if not isinstance(output_value, list):
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )
                else:
                    # For other generic types, fall back to standard type checking
                    if not isinstance(output_value, actual_type):
                        # Allow for flexible matching of generic types
                        try:
                            # Try to compare the underlying types more flexibly
                            if hasattr(actual_type, '__args__') and hasattr(output_value, '__class__'):
                                # For cases like typing.Dict[str, str] vs dict, check if it's the right type
                                if actual_type.__origin__ is dict and isinstance(output_value, dict):
                                    pass  # This is acceptable
                                elif actual_type.__origin__ is list and isinstance(output_value, list):
                                    pass  # This is acceptable
