def _save_dummy_outputs(
    output_annotations: List[
        Union[
            Tuple[type, Union[Parameter, Artifact]],
            Union[Type[OutputV1], Type[OutputV2]],
        ]
    ],
) -> None:
    """Save dummy values into the outputs specified.

    This function is used at runtime by the Hera Runner to create files in the container so that Argo
    does not log confusing error messages that obfuscate the real error, which look like:
    ```
    msg="cannot save parameter /tmp/hera-outputs/parameters/my-parameter"
    argo=true
    error="open /tmp/hera-outputs/parameters/my-parameter: no such file or directory"`
    ```

    The output annotations are used to write files using the schema:
    <parent_directory>/artifacts/<name>
    <parent_directory>/parameters/<name>
    If the artifact path or parameter value_from.path is specified, that is used instead.
    <parent_directory> can be provided by the user or is set to /tmp/hera-outputs by default
    """
    for dest in output_annotations:
        if isinstance(dest, type) and issubclass(dest, (OutputV1, OutputV2)):
            if os.environ.get("hera__script_pydantic_io", None) is None:
                raise ValueError("hera__script_pydantic_io environment variable is not set")

            for field in get_fields(dest):
                if field in {"exit_code", "result"}:
                    continue

                annotation = dest._get_output(field)
                path = _get_outputs_path(annotation)
                _write_to_path(path, "")
        else:
            assert isinstance(dest, tuple)
            if not dest[1].name:
                raise ValueError("The name was not provided for one of the outputs.")

            path = _get_outputs_path(dest[1])
            _write_to_path(path, "")


def _write_to_path(path: Path, output_value: Any, dumper: Callable = serialize) -> None:
    """Write the output_value as serialized text to the provided path. Create the necessary parent directories."""
    # Special handling for bytes data
    if isinstance(output_value, bytes):
        # For bytes, write directly as bytes
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(output_value)
        return

    # Special handling for non-base Pydantic models - use their dumps method if available
    from hera.shared._pydantic import BaseModel
    if isinstance(output_value, BaseModel):
        # This is a Pydantic model, try to use its dumps method if available
        if hasattr(output_value, 'dumps') and callable(getattr(output_value, 'dumps')):
            output_string = output_value.dumps()
        else:
            # Fall back to standard serialization
            output_string = dumper(output_value)
    else:
        output_string = dumper(output_value)

    if output_string is not None:
        # Ensure path is a file path, not a directory path
        # If the path is a directory, we should create a file inside it with a default name
        if path.is_dir():
            # Create a file inside the directory with a default name
            path = path / "output"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(output_string)

"""A serialization module that contains utilities for serializing any values passed to the Argo server via Hera."""

import json
from json import JSONEncoder
from typing import Any, Optional

from pydantic import BaseModel

# NOTE: Use the original BaseModel in order to support serializing user-defined models,
# for hera internal models, we still need to support v1 base models.
from hera.shared._pydantic import _PYDANTIC_VERSION

if _PYDANTIC_VERSION == 2:
    from pydantic.v1 import BaseModel as V1BaseModel  # type: ignore
else:
    V1BaseModel = None  # type: ignore

MISSING = object()
"""`MISSING` is a placeholder that indicates field value nullity.

When the user of a Hera object sets the field of an object specifically to `None`, Hera needs to distinguish between
default nullity/None and user-provided `None` on, say, something like the `source` of `Script`.
"""


class PydanticEncoder(JSONEncoder):
    """Default serializer of Hera objects."""

    def default(self, o: Any):
        """Return the default representation of the given object."""
        # Note that these are slightly different outputs b/w v1 and v2
        # v1 will give the actual python object whereas v2 will serialize it into
        # a json compatible format.
        if _PYDANTIC_VERSION == 1:
            if isinstance(o, BaseModel):
                return o.dict(by_alias=True)
        else:
            if isinstance(o, BaseModel):
                return o.model_dump(by_alias=True, mode="json")  # type: ignore
            if isinstance(o, V1BaseModel):
                return o.dict(by_alias=True)
        # Handle bytes and non-Pydantic objects
        if isinstance(o, bytes):
            return o.decode('utf-8', errors='ignore')
        # For other non-serializable objects, try to convert to string
        try:
            return str(o)
        except Exception:
            # If all else fails, return a representation
            return repr(o)
        return super().default(o)


def serialize(value: Any) -> Optional[str]:
    """Serialize the given value.

    If the value is `MISSING` then a proper `None` is returned. Since strings are "serialized" already, they are simply
    returned. Everything else is JSON encoded and returned.
    """
    if value == MISSING:
        return None
    elif isinstance(value, str):
        return value
    else:
        return json.dumps(value, cls=PydanticEncoder, default=str)  # None serialized as `null`

